import{_ as a,o as e,c as o,a5 as i}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"DO","description":"","frontmatter":{"title":"DO","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/DO.md","filePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/DO.md"}'),l={name:"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/DO.md"};function r(s,t,p,n,u,c){return e(),o("div",null,[...t[0]||(t[0]=[i("<div><p>package cn.iocoder.yudao.module.place.dal.dataobject;</p><p>import cn.iocoder.yudao.framework.mybatis.core.dataobject.BaseDO; import com.baomidou.mybatisplus.annotation.KeySequence; import com.baomidou.mybatisplus.annotation.TableId; import com.baomidou.mybatisplus.annotation.TableName; import lombok.*;</p><p>/**</p><ul><li>地点 DO (Data Object)</li><li>该类定义了地点数据的属性及其Getter和Setter方法等。DO类通常与数据库的表结构一一对应，用于在应用程序中表示数据库中的一行数据。</li><li></li><li>@author 芋道源码 */ @TableName(&quot;place&quot;) // MyBatis-Plus注解，表名为 &quot;place&quot; @KeySequence(&quot;system_group_seq&quot;) // MyBatis-Plus注解，用于 Oracle、PostgreSQL、Kingbase、DB2、H2 数据库的主键自增。如果是 MySQL 等数据库，可不写。 @Data // Lombok注解，为类所有属性生成getter/setter方法 @EqualsAndHashCode(callSuper = true) // Lombok注解，生成equals方法和hashCode方法，并且可以使用父类的属性 @ToString(callSuper = true) // Lombok注解，生成toString方法，并且可以使用父类的属性 @Builder // Lombok注解，为类创建builder @NoArgsConstructor // Lombok注解，生成无参数构造方法 @AllArgsConstructor // Lombok注解，生成全参数构造方法 public class PlaceDO extends BaseDO {</li></ul><p>/**</p><ul><li>编号，代表唯一的地点ID */ @TableId // MyBatis-Plus注解，标识该字段为数据库表的主键 private Long id;</li></ul><p>/**</p><ul><li>名字，代表地点的名称 */ private String name;</li></ul><p>/**</p><ul><li>描述，代表对地点的描述信息 */ private String description;</li></ul><p>/**</p><ul><li>状态，代表地点的状态。取值由 {@link TODO common_status 对应的类} 枚举定义 */ private Byte status; }</li></ul><p>DO (Data Object) 是用于与数据库交互的对象，它与数据库中的表结构对应。</p><p>在 ORM（Object-Relational Mapping，对象-关系映射）中，我们通常使用 DO 对象来表示数据库中的一行数据。这样，我们可以在程序中通过操作 DO 对象来实现对数据库的增删改查。</p><p>在这个 PlaceDO 类中，id, name, description, status 等字段分别对应 place 表的各个字段。通过 @TableName、@TableId 等 MyBatis-Plus 的注解，我们将这些字段与数据库表结构关联起来。同时，通过 Lombok 的注解，如 @Data、@Builder、@NoArgsConstructor、@AllArgsConstructor 等，我们可以为这个 DO 类生成常用的 getter、setter 方法、无参/全参构造函数、以及 builder 模式等。</p></div>",1)])])}const b=a(l,[["render",r]]);export{m as __pageData,b as default};
